        Checks if this complex number is not equal to another complex number.
        :param that: The other complex number to compare with,ComplexNumber.
        :return: true if the complex numbers are not equal, false otherwise,Bool.
        */
        return this.real != that.real || this.imaginary != that.imaginary
    }

    public override operator func == (that: ComplexNumber): Bool {
        /*
        Checks if this complex number is equal to another complex number.
        :param that: The other complex number to compare with,ComplexNumber.
        :return: true if the complex numbers are equal, false otherwise,Bool.
        */
        return this.real == that.real && this.imaginary == that.imaginary
    }
}


class ComplexCalculator {

    /*
    This is a class that implements addition, subtraction, multiplication, and division operations for complex numbers.
    */

    public init() { }

    public static func add(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Adds two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The sum of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.add(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(4.0, 6.0)

        */
        let real = c1.real + c2.real
        let imaginary = c1.imaginary + c2.imaginary
        return ComplexNumber(real, imaginary)
    }

    public static func subtract(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Subtracts two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The difference of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.subtract(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(-2.0, -2.0)

        */
        let real = c1.real - c2.real
        let imaginary = c1.imaginary - c2.imaginary
        return ComplexNumber(real, imaginary)
    }

    public static func multiply(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Multiplies two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The product of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.multiply(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(-5.0, 10.0)

        */
        let real = c1.real * c2.real - c1.imaginary * c2.imaginary
        let imaginary = c1.real * c2.imaginary + c1.imaginary * c2.real
        return ComplexNumber(real, imaginary)
    }

    public static func divide(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        /*
        Divides two complex numbers.
        :param c1: The first complex number,ComplexNumber.
        :param c2: The second complex number,ComplexNumber.
        :return: The quotient of the two complex numbers,ComplexNumber.
        >>> ComplexCalculator.divide(ComplexNumber(1.0, 2.0), ComplexNumber(3.0, 4.0))
        ComplexNumber(0.44, 0.08)

        */
        let denominator = c2.real * c2.real + c2.imaginary * c2.imaginary
        let real = (c1.real * c2.real + c1.imaginary * c2.imaginary) / denominator
        let imaginary = (c1.imaginary * c2.real - c1.real * c2.imaginary) / denominator
        return ComplexNumber(real, imaginary)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    /*
    This is a class for processing CSV files, including readring and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        /*
        Read the csv file by file_name, get the title and data from it
        :param file_name: String, name of the csv file
        :return title, data: (ArrayList<String>, ArrayList<ArrayList<String>>), first row is title, the rest is data
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        */
        let file_content = fs::read_text_file(file_name).unwrap()
        let lines = file_content.split("\n")
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        if lines.length() == 0 {
            return (title, data)
        }

        // Parse title (first line)
        let title_parts = lines[0].split(",")
        for i in 0..title_parts.length() {
            title.add(title_parts[i].trim())
        }

        // Parse data (remaining lines)
        for i in 1..lines.length() {
            if lines[i].length() == 0 {
                continue // Skip empty lines
            }
            let row_parts = lines[i].split(",")
            let row = ArrayList<String>()
            for j in 0..row_parts.length() {
                row.add(row_parts[j].trim())
            }
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        /*
        Write data into a csv file.
        :param file_name: String, name of the csv file
        :return: Int64, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> data = ArrayList<ArrayList<String>>([ArrayList<String>(['a', 'b', 'c', 'd']), ArrayList<String>(['hElLo', 'YoU', 'ME', 'LoW'])])
        >>> csvProcessor.write_csv(data, 'write_test.csv')
        1
        */
        try {
            let mut content = String("")
            for i in 0..data.length() {
                let row = data[i]
                for j in 0..row.length() {
                    content = content.concat(row[j])
                    if j != row.length() - 1 {
                        content = content.concat(",")
                    }
                }
                if i != data.length() - 1 {
                    content = content.concat("\n")
                }
            }
            fs::write_text_file(file_name, content).unwrap()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        /*
        Read a csv file into variable title and data.
        Only remain the N th (from 0) column data and Capitalize them, store the title and new data into a new csv file.
        Add '_process' suffix after old file name, as a new file name.
        :param N: Int64, the N th column(from 0)
        :param save_file_name, the name of file that needs to be processed.
        :return:Int64, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        >>> csvProcessor.process_csv_data(0, 'read_test.csv')
        1
        >>> csvProcessor.read_csv('read_test_process.csv')
        (['a', 'b', 'c', 'd'], [['HELLO']])
        */
        let (title, data) = self.read_csv(save_file_name)

        // Extract the Nth column and capitalize
        let column_data = ArrayList<String>()
        for i in 0..data.length() {
            if N < data[i].length() {
                let cell = data[i][N]
                column_data.add(cell.to_upper_case())
            }
        }

        // Create new data with title and the processed column
        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)
        new_data.add(column_data)

        // Generate new file name with '_process' suffix
        let file_parts = save_file_name.split(".")
        let base_name = file_parts[0]
        let ext = if file_parts.length() > 1 { "." + file_parts[1] } else { "" }
        let new_file_name = base_name + "_process" + ext

        return self.write_csv(new_data, new_file_name)
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs

class CurrencyConverter {

    /*
    This is a class for currency conversion, which supports to convert amounts between different currencies, retrieve supported currencies, add new currency rates, and update existing currency rates.
    */

    let rates: HashMap<String, Float64>

    public init() {
        /*
        Initialize the exchange rate of the US dollar against various currencies
        */
        this.rates = HashMap<String, Float64>()
        this.rates.add('USD', 1.0)
        this.rates.add('EUR', 0.85)
        this.rates.add('GBP', 0.72)
        this.rates.add('JPY', 110.15)
        this.rates.add('CAD', 1.23)
        this.rates.add('AUD', 1.34)
        this.rates.add('CNY', 6.40)
    }

    public func convert(amount: Float64, from_currency: String, to_currency: String): Float64 {
        /*
        Convert the value of a given currency to another currency type
        :param amount: Float64, The value of a given currency
        :param from_currency: String, source currency type
        :param to_currency: String, target currency type
        :return: Float64, value converted to another currency type
        >>> cc = CurrencyConverter()
        >>> cc.convert(64.0, 'CNY','USD')
        10.0
        */
        if (from_currency == to_currency) {
            return amount
        }

        let from_rate = this.rates.get(from_currency)
        let to_rate = this.rates.get(to_currency)

        if (from_rate == None || to_rate == None) {
            return -1.0  // Using -1.0 to indicate error as Bool return type is not compatible with the function signature
        }

        return (amount / from_rate!) * to_rate!
    }

    public func get_supported_currencies(): ArrayList<String> {
        /*
        Returns a list of supported currency types
        :return: ArrayList<String>, All supported currency types
        >>> cc = CurrencyConverter()
        >>> cc.get_supported_currencies()
        ['USD','EUR','GBP','JPY','CAD','AUD','CNY']
        */
        let currencies = ArrayList<String>()
        for (entry in this.rates) {
            currencies.add(entry.0)
        }
        return currencies
    }

    public func add_currency_rate(currency: String, rate: Float64): Bool {
        /*
        Add a new supported currency type, return false if the currency type is already in the support list
        :param currency:String, currency type to be added
        :param rate:Float64, exchange rate for this type of currency
        :return:If successful, returns true; if unsuccessful, returns false
        >>> cc = CurrencyConverter()
        >>> cc.add_currency_rate('KRW', 1308.84)
        true
        this.rates['KRW'] = 1308.84
        */
        if (this.rates.get(currency) != None) {
            return false
        }
        this.rates.add(currency, rate)
        return true
    }

    public func update_currency_rate(currency: String, new_rate: Float64): Bool {
        /*
        Update the exchange rate for a certain currency
        :param currency:String
        :param new_rate:Float64
        :return:If successful, returns true; if unsuccessful, returns false
        >>> cc = CurrencyConverter()
        >>> cc.update_currency_rate('CNY', 7.18)
        true
        this.rates['CNY'] = 7.18
        */
        if (this.rates.get(currency) == None) {
            return false
        }
        this.rates.add(currency, new_rate)
        return true
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    /*
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    */

    public func mean(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean(ArrayList<Int64>([1, 2, 3, 4, 5]))
        3.00
        */
        if (data.size == 0) {
            return 0.0
        }

        var sum: Float64 = 0.0
        for (value in data) {
            sum += value.toFloat64()
        }
        var meanValue: Float64 = sum / data.size.toFloat64()
        // Round to 2 decimal places
        meanValue = round(meanValue * 100.0) / 100.0
        return meanValue
    }

    public func median(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the median value
        >>> ds = DataStatistics()
        >>> ds.median(ArrayList<Int64>([2, 5, 1, 3, 4]))
        3.00
        */
        if (data.size == 0) {
            return 0.0
        }

        var sortedData = data.clone()
        sort<Int64>(sortedData)

        let n = sortedData.size
        var medianValue: Float64

        if (n % 2 == 0) {
            let middle = n / 2
            let left = sortedData[middle - 1].toFloat64()
            let right = sortedData[middle].toFloat64()
            medianValue = (left + right) / 2.0
        } else {
            let middle = n / 2
            medianValue = sortedData[middle].toFloat64()
        }

        // Round to 2 decimal places
        medianValue = round(medianValue * 100.0) / 100.0
        return medianValue
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        Calculate the mode of a set of data
        :param data:ArrayList<Int64>, data list
        :return:ArrayList<Int64>, the mode
        >>> ds = DataStatistics()
        >>> ds.mode(ArrayList<Int64>([2, 2, 3, 3, 4]))
        [2, 3]
        */
        if (data.size == 0) {
            return ArrayList<Int64>()
        }

        var counter: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for (value in data) {
            if (counter.contains(value)) {
                let currentCount = counter[value]!
                counter.add(value, currentCount + 1)
            } else {
                counter.add(value, 1)
            }
        }

        var maxCount: Int64 = 0
        for ((_, count) in counter) {
            if (count > maxCount) {
                maxCount = count
            }
        }

        var modes: ArrayList<Int64> = ArrayList<Int64>()
        for ((value, count) in counter) {
            if (count == maxCount) {
                modes.add(value)
            }
        }

        // Sort the modes for consistent output
        sort<Int64>(modes)
        return modes
    }
}

import std.collection.ArrayList
