class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for i in 0..this.data.size() {
            sum += this.data.get(i)
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        if this.data.size() == 0 {
            return 0.0
        }
        var min_val: Float64 = this.data.get(0)
        for i in 1..this.data.size() {
            if this.data.get(i) < min_val {
                min_val = this.data.get(i)
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        if this.data.size() == 0 {
            return 0.0
        }
        var max_val: Float64 = this.data.get(0)
        for i in 1..this.data.size() {
            if this.data.get(i) > max_val {
                max_val = this.data.get(i)
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        if this.data.size() == 0 {
            return 0.0
        }

        // Calculate mean
        var sum: Float64 = 0.0
        for i in 0..this.data.size() {
            sum += this.data.get(i)
        }
        var mean: Float64 = sum / this.data.size().toFloat64()

        // Calculate variance
        var variance_sum: Float64 = 0.0
        for i in 0..this.data.size() {
            var diff: Float64 = this.data.get(i) - mean
            variance_sum += diff * diff
        }
        var variance: Float64 = variance_sum / this.data.size().toFloat64()

        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        var variance: Float64 = this.get_variance()
        var std_dev: Float64 = sqrt(variance)
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        // For a single dataset, correlation is typically 1.0 with itself
        // This is a simplified implementation for the purpose of the example
        return 1.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    /*
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    */

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        /*
        Calculate the correlation coefficient of two sets of data.
        :param data1: The first set of data,ArrayList<Float64>.
        :param data2: The second set of data,ArrayList<Float64>.
        :return: The correlation coefficient, Float64.
        >>> DataStatistics4.correlation_coefficient(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]))
        0.9999999999999998

        */
        let n: Int32 = data1.size().intCast()
        if n != data2.size().intCast() {
            return 0.0
        }

        if n == 0 {
            return 0.0
        }

        // Calculate means
        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        var i: Int32 = 0
        while i < n {
            sum1 += data1.get(i).getOrThrow()
            sum2 += data2.get(i).getOrThrow()
            i += 1
        }

        let mean1: Float64 = sum1 / n.floatCast()
        let mean2: Float64 = sum2 / n.floatCast()

        // Calculate numerator and denominators
        var numerator: Float64 = 0.0
        var sum_sq_diff1: Float64 = 0.0
        var sum_sq_diff2: Float64 = 0.0
        i = 0
        while i < n {
            let diff1: Float64 = data1.get(i).getOrThrow() - mean1
            let diff2: Float64 = data2.get(i).getOrThrow() - mean2
            numerator += diff1 * diff2
            sum_sq_diff1 += diff1 * diff1
            sum_sq_diff2 += diff2 * diff2
            i += 1
        }

        let denominator: Float64 = sqrt(sum_sq_diff1) * sqrt(sum_sq_diff2)
        return if denominator != 0.0 { numerator / denominator } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the skewness of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The skewness, Float64.
        >>> DataStatistics4.skewness(ArrayList<Float64>([1.0, 2.0, 5.0]))
        2.3760224064818463

        */
        let n: Int32 = data.size().intCast()
        if n < 3 {
            return 0.0
        }

        // Calculate mean
        var sum: Float64 = 0.0
        var i: Int32 = 0
        while i < n {
            sum += data.get(i).getOrThrow()
            i += 1
        }
        let mean: Float64 = sum / n.floatCast()

        // Calculate variance and std deviation
        var sum_sq_diff: Float64 = 0.0
        i = 0
        while i < n {
            let diff: Float64 = data.get(i).getOrThrow() - mean
            sum_sq_diff += diff * diff
            i += 1
        }
        let variance: Float64 = sum_sq_diff / n.floatCast()
        let std_deviation: Float64 = sqrt(variance)

        if std_deviation == 0.0 {
            return 0.0
        }

        // Calculate skewness
        var sum_cubed_diff: Float64 = 0.0
        i = 0
        while i < n {
            let diff: Float64 = data.get(i).getOrThrow() - mean
            sum_cubed_diff += diff * diff * diff
            i += 1
        }

        let skewness: Float64 = sum_cubed_diff * n.floatCast() / ((n - 1).floatCast() * (n - 2).floatCast() * std_deviation * std_deviation * std_deviation)
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the kurtosis of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The kurtosis, Float64.
        >>> DataStatistics4.kurtosis(ArrayList<Float64>([1.0, 2.0, 5.0]))
        -1.5000000000000007

        */
        let n: Int32 = data.size().intCast()
        if n < 4 {
            return 0.0
        }

        // Calculate mean
        var sum: Float64 = 0.0
        var i: Int32 = 0
        while i < n {
            sum += data.get(i).getOrThrow()
            i += 1
        }
        let mean: Float64 = sum / n.floatCast()

        // Calculate std deviation
        var sum_sq_diff: Float64 = 0.0
        i = 0
        while i < n {
            let diff: Float64 = data.get(i).getOrThrow() - mean
            sum_sq_diff += diff * diff
            i += 1
        }
        let std_dev: Float64 = sqrt(sum_sq_diff / n.floatCast())

        if std_dev == 0.0 {
            return Float64.getNaN()
        }

        // Calculate fourth moment
        var fourth_moment: Float64 = 0.0
        i = 0
        while i < n {
            let diff: Float64 = data.get(i).getOrThrow() - mean
            fourth_moment += diff * diff * diff * diff
            i += 1
        }
        fourth_moment = fourth_moment / n.floatCast()

        let kurtosis_value: Float64 = (fourth_moment / (std_dev * std_dev * std_dev * std_dev)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        /*
        Calculate the probability density function (PDF) of a set of data under a normal distribution.
        :param data: The input data list, ArrayList<Float64>.
        :param mu: The mean of the normal distribution, Float64.
        :param sigma: The standard deviation of the normal distribution, Float64.
        :return: The probability density function (PDF), ArrayList<Float64>.
        >>> DataStatistics4.pdf(ArrayList<Float64>([1.0, 2.0, 3.0]), 1.0, 1.0)
        [0.3989422804014327, 0.24197072451914337, 0.05399096651318806]

        */
        if sigma == 0.0 {
            // Return a list of infinite values or zeros depending on implementation
            let result: ArrayList<Float64> = ArrayList<Float64>(data.size())
            var i: Int32 = 0
            let n: Int32 = data.size().intCast()
            while i < n {
                result.add(0.0)
                i += 1
            }
            return result
        }

        let sqrt_2pi: Float64 = sqrt(2.0 * Float64.getPI())
        let coefficient: Float64 = 1.0 / (sigma * sqrt_2pi)

        let result: ArrayList<Float64> = ArrayList<Float64>(data.size())
        var i: Int32 = 0
        let n: Int32 = data.size().intCast()
        while i < n {
            let x: Float64 = data.get(i).getOrThrow()
            let exponent: Float64 = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            let pdf_value: Float64 = coefficient * exp(exponent)
            result.add(pdf_value)
            i += 1
        }

        return result
    }
}

