    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var plaintext: String = ""
        for (char in ciphertext) {
            if char.isAlpha() {
                var ascii_offset: Int64
                if char.isUpper() {
                    ascii_offset = 65
                } else {
                    ascii_offset = 97
                }
                let shifted_char = String.fromCharCode(Int64((Int64(char.toCodePoint()) - ascii_offset - shift) % 26 + ascii_offset))
                plaintext = plaintext.concat(shifted_char)
            } else {
                plaintext = plaintext.concat(String.fromChar(char))
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        var decrypted_text: String = ""
        var key_index: Int64 = 0
        for (char in ciphertext) {
            if char.isAlpha() {
                let key_char = this.key[Int(key_index % Int(this.key.length()))].lower()
                let shift = Int64(key_char.toCodePoint()) - Int64('a'.toCodePoint())
                let decrypted_char_code = (Int64(char.lower().toCodePoint()) - Int64('a'.toCodePoint()) - shift) % 26
                let decrypted_char = String.fromCharCode(decrypted_char_code + Int64('a'.toCodePoint()))
                if char.isUpper() {
                    decrypted_text = decrypted_text.concat(decrypted_char.upper())
                } else {
                    decrypted_text = decrypted_text.concat(decrypted_char)
                }
                key_index += 1
            } else {
                decrypted_text = decrypted_text.concat(String.fromChar(char))
            }
        }
        return decrypted_text
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        // Create a fence matrix
        var fence: [[String]] = []
        for (i in 0..rails) {
            var row: [String] = []
            for (j in 0..Int64(encrypted_text.length())) {
                row.append("\n")
            }
            fence.append(row)
        }

        var direction: Int64 = -1
        var row: Int64 = 0
        var col: Int64 = 0

        for (i in 0..Int64(encrypted_text.length())) {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }

            fence[Int(row)][Int(col)] = ""
            col += 1
            row += direction
        }

        var index: Int64 = 0
        for (i in 0..rails) {
            for (j in 0..Int64(encrypted_text.length())) {
                if fence[Int(i)][Int(j)] == "" {
                    fence[Int(i)][Int(j)] = String.fromChar(encrypted_text[Int(index)])
                    index += 1
                }
            }
        }

        var plain_text: String = ""
        direction = -1
        row = 0
        col = 0
        for (i in 0..Int64(encrypted_text.length())) {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }

            plain_text = plain_text.concat(fence[Int(row)][Int(col)])
            col += 1
            row += direction
        }

        return plain_text
    }
}

