class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        let octets = ip_address.split('.')
        if octets.size() != 4 {
            return false
        }
        for (let i = 0; i < octets.size(); i = i + 1) {
            let octet = octets[i]
            if !is_digit(octet) || string_to_int(octet) < 0 || string_to_int(octet) > 255 {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        if is_valid() {
            let result = ArrayList<String>()
            let octets = ip_address.split('.')
            for (let i = 0; i < octets.size(); i = i + 1) {
                result.add(octets[i])
            }
            return result
        } else {
            return ArrayList<String>()
        }
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        if !is_valid() {
            return ""
        }
        let octets = get_octets()
        let binary_octets = ArrayList<String>()
        for (let i = 0; i < octets.size(); i = i + 1) {
            let octet = octets[i]
            let num = string_to_int(octet)
            let binary = format_to_8bit_binary(num)
            binary_octets.add(binary)
        }
        let result = ""
        for (let i = 0; i < binary_octets.size(); i = i + 1) {
            if i == 0 {
                result = result + binary_octets[i]
            } else {
                result = result + "." + binary_octets[i]
            }
        }
        return result
    }

    private func is_digit(s: String): Bool {
        if s.length() == 0 {
            return false
        }
        for (let i = 0; i < s.length(); i = i + 1) {
            let c = s[i]
            if c < '0' || c > '9' {
                return false
            }
        }
        // Check if string has leading zeros (except for "0" itself)
        if s.length() > 1 && s[0] == '0' {
            return false
        }
        return true
    }

    private func string_to_int(s: String): Int {
        var result: Int = 0
        for (let i = 0; i < s.length(); i = i + 1) {
            let c = s[i]
            result = result * 10 + (c - '0')
        }
        return result
    }

    private func format_to_8bit_binary(num: Int): String {
        var result = ""
        var n = num
        for (let i = 0; i < 8; i = i + 1) {
            if (n & (1 << (7 - i))) != 0 {
                result = result + "1"
            } else {
                result = result + "0"
            }
        }
        return result
    }
}

