class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        if (this.word_list.isEmpty()) {
            return ""
        }

        // Convert sentence to lowercase
        let lower_sentence = sentence.toLowerCase()

        // Remove punctuation marks using regex
        let regex = Regex("[\\p{Punct}\\s]+")
        let cleaned_sentence = regex.replaceAll(lower_sentence, " ")

        // Split into words
        let words = cleaned_sentence.split(" ")

        let mut longest_word = ""

        for word in words {
            let trimmed_word = word.trim()
            if (!trimmed_word.isEmpty() && this.word_list.contains(trimmed_word) && 
                trimmed_word.length() > longest_word.length()) {
                longest_word = trimmed_word
            }
        }

        return longest_word
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    /*
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    */

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        /*
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of String, representing the icons
        >>>mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.BOARD_SIZE = [4, 4]
        mc.ICONS = ['a', 'b', 'c']
        mc.board = mc.create_board()
        */
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        create the game board with the given board size and icons
        :return: 2-dimensional list, the game board
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.create_board()
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        var board: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let rand = Random()

        for (i in 0..rows) {
            var row: ArrayList<String> = ArrayList<String>()
            for (j in 0..cols) {
                let icon_index = rand.next() % ICONS.size()
                row.add(ICONS[icon_index])
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if the move of two icons is valid (i.e. positions are within the game board range, the two positions are not the same, the two positions have the same icon, and there is a valid path between the two positions)
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return:true or false ,representing whether the move of two icons is valid
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.is_valid_move((0, 0), (1, 0))
        true
        */
        let x1 = pos1.0
        let y1 = pos1.1
        let x2 = pos2.0
        let y2 = pos2.1

        // Check if positions are within the game board range
        if (!(0 <= x1 && x1 < this.BOARD_SIZE[0] && 0 <= y1 && y1 < this.BOARD_SIZE[1] && 
              0 <= x2 && x2 < this.BOARD_SIZE[0] && 0 <= y2 && y2 < this.BOARD_SIZE[1])) {
            return false
        }

        // Check if the two positions are the same
        if (pos1 == pos2) {
            return false
        }

        // Check if the two positions have the same icon
        if (this.board[x1.toInt()][y1.toInt()] != this.board[x2.toInt()][y2.toInt()]) {
            return false
        }

        // Check if there is a valid path between the two positions
        if (!this.has_path(pos1, pos2)) {
            return false
        }

        return true
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if there is a path between two icons
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return: true or false ,representing whether there is a path between two icons
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.has_path((0, 0), (1, 0))
        true
        */
        var visited: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        var stack: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        stack.add(pos1)

        while (!stack.isEmpty()) {
            let current_pos = stack.pop()
            if (current_pos == pos2) {
                return true
            }

            if (MahjongConnect.contains(visited, current_pos)) {
                continue
            }

            visited.add(current_pos)
            let x = current_pos.0
            let y = current_pos.1

            // Check adjacent positions (up, down, left, right)
            let directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for (dir in directions) {
                let dx = dir.0
                let dy = dir.1
                let new_x = x + dx
                let new_y = y + dy

                if (0 <= new_x && new_x < this.BOARD_SIZE[0] && 0 <= new_y && new_y < this.BOARD_SIZE[1]) {
                    let new_pos = (new_x, new_y)
                    if (!MahjongConnect.contains(visited, new_pos) && 
                        this.board[new_x.toInt()][new_y.toInt()] == this.board[x.toInt()][y.toInt()]) {
                        stack.add(new_pos)
                    }
                }
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        /*
        check if the position is in the visited list
        :param visited: list of position tuples, representing the visited positions
        :param pos: position tuple, representing the position to be checked
        :return: true or false, representing whether the position is in the visited list
        */
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        /*
        remove the connected icons on the game board
        :param pos1: position tuple(x, y) of the first icon to be removed
        :param pos2: position tuple(x, y) of the second icon to be removed
        :return: Unit
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.remove_icons((0, 0), (1, 0))
        mc.board = [[' ', 'b', 'c', 'a'],
                    [' ', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        let x1 = pos1.0
        let y1 = pos1.1
        let x2 = pos2.0
        let y2 = pos2.1

        this.board[x1.toInt()][y1.toInt()] = " "
        this.board[x2.toInt()][y2.toInt()] = " "
    }

    public func is_game_over(): Bool {
        /*
        Check if the game is over (i.e., if there are no more icons on the game board)
        :return: true or false ,representing whether the game is over
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.board = [[' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' ']]
        >>> mc.is_game_over()
        true
        */
        for (row in this.board) {
            for (icon in row) {
                if (icon != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    /*
    his is a class that implements a manacher algorithm to find the Longest palindromic substring in a given string.
    */

    let input_string: String

    public init(input_string: String) {
        /*
        Initializes the Manacher class with the given input_string.
        :param input_string: The input_string to be searched, String.
        */
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        /*
        Recursively calculates the length of the palindromic substring based on a given center, difference value, and input string.
        :param center: The center of the palindromic substring, Int64.
        :param diff: The difference between the center and the current position, Int64.
        :param string: The string to be searched, String.
        :return: The length of the palindromic substring, Int64.
        >>> manacher = Manacher('ababa')
        >>> manacher.palindromic_length(2, 1, 'a|b|a|b|a')
        2

        */
        if (center - diff == -1 || center + diff == string.length() 
                || string.get(center - diff) != string.get(center + diff)) {
            return 0
        }
        return 1 + this.palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        /*
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, String.
        >>> manacher = Manacher('ababaxse')
        >>> manacher.palindromic_string()
        'ababa'

        */
        var max_length: Int64 = 0
        var new_input_string: String = ""
        var output_string: String = ""

        for i in 0..(this.input_string.length() - 1) {
            new_input_string = new_input_string + this.input_string.get(i) + "|"
        }
        if (this.input_string.length() > 0) {
            new_input_string = new_input_string + this.input_string.get(this.input_string.length() - 1)
        }

        var start: Int64 = 0
        for i in 0..new_input_string.length() {
            var length: Int64 = this.palindromic_length(i, 1, new_input_string)

            if max_length < length {
                max_length = length
                start = i
            }
        }

        var temp_string: String = ""
        for i in (start - max_length)..(start + max_length + 1) {
            if i >= 0 && i < new_input_string.length() {
                var c: Char = new_input_string.get(i)
                if c != '|' {
                    temp_string = temp_string + c.toString()
                }
            }
        }
        output_string = temp_string

        return output_string
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        for (i in 0 ..< predicted_labels.size) {
            let predicted = predicted_labels.get(i)
            let true_label = true_labels.get(i)
            if (predicted == 1 && true_label == 1) {
                this.true_positives += 1
            } else if (predicted == 1 && true_label == 0) {
                this.false_positives += 1
            } else if (predicted == 0 && true_label == 1) {
                this.false_negatives += 1
            } else if (predicted == 0 && true_label == 0) {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        if (this.true_positives + this.false_positives == 0) {
            return 0.0
        }
        return this.true_positives as Float64 / (this.true_positives + this.false_positives) as Float64
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        if (this.true_positives + this.false_negatives == 0) {
            return 0.0
        }
        return this.true_positives as Float64 / (this.true_positives + this.false_negatives) as Float64
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let precision_val = this.precision(predicted_labels, true_labels)
        let recall_val = this.recall(predicted_labels, true_labels)
        if (precision_val + recall_val == 0.0) {
            return 0.0
        }
        return (2.0 * precision_val * recall_val) / (precision_val + recall_val)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let total = this.true_positives + this.true_negatives + this.false_positives + this.false_negatives
        if (total == 0) {
            return 0.0
        }
        return (this.true_positives + this.true_negatives) as Float64 / total as Float64
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MRR of the input data. MRR is a widely used evaluation index. It is the mean of reciprocal rank.
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.mrr((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.mrr([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        1.0, [1.0]
        0.75, [1.0, 0.5]
        */

        // Check if data is ArrayList or tuple equivalent
        if data is! ArrayList && data is! Tuple {
            throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        }

        if data is ArrayList {
            let dataList: ArrayList = data as ArrayList
            if dataList.isEmpty() {
                let result: ArrayList<Float64> = ArrayList<Float64>()
                result.add(0.0)
                return (0.0, result)
            }

            let separateResult: ArrayList<Float64> = ArrayList<Float64>()
            for item in dataList {
                if item is! Tuple {
                    throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
                }

                let tupleItem: Tuple = item as Tuple
                if tupleItem.size() != 2 {
                    throw Exception("tuple must contain 2 elements: (sub_list, total_num)")
                }

                let subList: ArrayList<Int64> = tupleItem.get(0) as ArrayList<Int64>
                let totalNum: Int64 = tupleItem.get(1) as Int64

                if totalNum == 0 {
                    separateResult.add(0.0)
                } else {
                    var mr: Float64 = 0.0
                    for i in 0 ..< subList.size() {
                        if subList.get(i) == 1 {
                            mr = 1.0 / (i + 1) as Float64
                            break
                        }
                    }
                    separateResult.add(mr)
                }
            }

            var sum: Float64 = 0.0
            for mr in separateResult {
                sum += mr
            }
            let mean: Float64 = sum / separateResult.size() as Float64
            return (mean, separateResult)
        } else {
            // data is a single tuple
            let tuple: Tuple = data as Tuple
            if tuple.size() != 2 {
                throw Exception("tuple must contain 2 elements: (sub_list, total_num)")
            }

            let subList: ArrayList<Int64> = tuple.get(0) as ArrayList<Int64>
            let totalNum: Int64 = tuple.get(1) as Int64

            if totalNum == 0 {
                let result: ArrayList<Float64> = ArrayList<Float64>()
                result.add(0.0)
                return (0.0, result)
            } else {
                var mr: Float64 = 0.0
                for i in 0 ..< subList.size() {
                    if subList.get(i) == 1 {
                        mr = 1.0 / (i + 1) as Float64
                        break
                    }
                }
                let result: ArrayList<Float64> = ArrayList<Float64>()
                result.add(mr)
                return (mr, result)
            }
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        /*
        compute the MAP of the input data. MAP is a widely used evaluation index. It is the mean of AP (average precision).
        :param data: the data must be a tuple, list 0,1,eg.([1,0,...],5).  In each tuple (actual result,ground truth num),ground truth num is the total ground num.
         ([1,0,...],5),
        or list of tuple eg. [([1,0,1,...],5),([1,0,...],6),([0,0,...],5)].
        1 stands for a correct answer, 0 stands for a wrong answer.
        :return: if input data is list, return the recall of this list. if the input data is list of list, return the
        average recall on all list. The second return value is a list of precision for each input.
        >>> MetricsCalculator2.map((ArrayList<Int64>([1, 0, 1, 0]), 4))
        >>> MetricsCalculator2.map([(ArrayList<Int64>([1, 0, 1, 0]), 4), (ArrayList<Int64>([0, 1, 0, 1]), 4)])
        0.41666666666666663, [0.41666666666666663]
        0.3333333333333333, [0.41666666666666663, 0.25]
        */

        // Check if data is ArrayList or tuple equivalent
        if data is! ArrayList && data is! Tuple {
            throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        }

        if data is ArrayList {
            let dataList: ArrayList = data as ArrayList
            if dataList.isEmpty() {
                let result: ArrayList<Float64> = ArrayList<Float64>()
                result.add(0.0)
                return (0.0, result)
            }

            let separateResult: ArrayList<Float64> = ArrayList<Float64>()
            for item in dataList {
                if item is! Tuple {
                    throw Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
                }

                let tupleItem: Tuple = item as Tuple
                if tupleItem.size() != 2 {
                    throw Exception("tuple must contain 2 elements: (sub_list, total_num)")
                }

                let subList: ArrayList<Int64> = tupleItem.get(0) as ArrayList<Int64>
                let totalNum: Int64 = tupleItem.get(1) as Int64

                if totalNum == 0 {
                    separateResult.add(0.0)
                } else {
                    var correctCount: Int64 = 0
                    var cumulativePrecision: Float64 = 0.0

                    for i in 0 ..< subList.size() {
                        if subList.get(i) == 1 {
                            correctCount += 1
                            let precision: Float64 = correctCount as Float64 / (i + 1) as Float64
                            cumulativePrecision += precision
                        }
                    }

                    var averagePrecision: Float64 = 0.0
                    if correctCount > 0 {
                        averagePrecision = cumulativePrecision / totalNum as Float64
                    }
                    separateResult.add(averagePrecision)
                }
            }

            var sum: Float64 = 0.0
            for ap in separateResult {
                sum += ap
            }
            let mean: Float64 = sum / separateResult.size() as Float64
            return (mean, separateResult)
        } else {
            // data is a single tuple
            let tuple: Tuple = data as Tuple
            if tuple.size() != 2 {
                throw Exception("tuple must contain 2 elements: (sub_list, total_num)")
            }

            let subList: ArrayList<Int64> = tuple.get(0) as ArrayList<Int64>
            let totalNum: Int64 = tuple.get(1) as Int64

            if totalNum == 0 {
                let result: ArrayList<Float64> = ArrayList<Float64>()
                result.add(0.0)
                return (0.0, result)
            } else {
                var correctCount: Int64 = 0
                var cumulativePrecision: Float64 = 0.0

                for i in 0 ..< subList.size() {
                    if subList.get(i) == 1 {
                        correctCount += 1
                        let precision: Float64 = correctCount as Float64 / (i + 1) as Float64
                        cumulativePrecision += precision
                    }
                }

                var averagePrecision: Float64 = 0.0
                if correctCount > 0 {
                    averagePrecision = cumulativePrecision / totalNum as Float64
                }

                let result: ArrayList<Float64> = ArrayList<Float64>()
                result.add(averagePrecision)
                return (averagePrecision, result)
            }
        }
    }
}

import std.collection.ArrayList
