class MinesweeperGame {

    /*
    This is a class that implements mine sweeping games including minesweeping and winning judgment.
    */

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        /*
        Initializes the MinesweeperGame class with the size of the board and the number of mines.
        :param n: The size of the board, Int64.
        :param k: The number of mines, Int64.
        */
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a minesweeper map with the given size of the board and the number of mines,the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'X' represents the mine,other numbers represent the number of mines around the position.
        :return: The minesweeper map, ArrayList<ArrayList<String>>.
        >>> MinesweeperGame.generate_mine_sweeper_map(3)
        [['X', '1', '0'], ['1', '1', '0'], ['0', '0', '0']]

        */
        let arr = ArrayList<ArrayList<String>>()
        for (let i = 0; i < n; i = i + 1) {
            let row = ArrayList<String>()
            for (let j = 0; j < n; j = j + 1) {
                row.add("0")
            }
            arr.add(row)
        }

        let random = Random()
        for (let num = 0; num < k; num = num + 1) {
            let x = random.nextInt() % n
            let y = random.nextInt() % n
            if (x < 0) {
                x = -x
            }
            if (y < 0) {
                y = -y
            }
            arr.get(y).set(x, "X")

            if (x >= 0 && x <= n - 2) && (y >= 0 && y <= n - 1) {
                if (!arr.get(y).get(x + 1).equals("X")) {
                    let current = arr.get(y).get(x + 1).parseInt(10)
                    arr.get(y).set(x + 1, (current + 1).toString())
                }
            }
            if (x >= 1 && x <= n - 1) && (y >= 0 && y <= n - 1) {
                if (!arr.get(y).get(x - 1).equals("X")) {
                    let current = arr.get(y).get(x - 1).parseInt(10)
                    arr.get(y).set(x - 1, (current + 1).toString())
                }
            }
            if (x >= 1 && x <= n - 1) && (y >= 1 && y <= n - 1) {
                if (!arr.get(y - 1).get(x - 1).equals("X")) {
                    let current = arr.get(y - 1).get(x - 1).parseInt(10)
                    arr.get(y - 1).set(x - 1, (current + 1).toString())
                }
            }
            if (x >= 0 && x <= n - 2) && (y >= 1 && y <= n - 1) {
                if (!arr.get(y - 1).get(x + 1).equals("X")) {
                    let current = arr.get(y - 1).get(x + 1).parseInt(10)
                    arr.get(y - 1).set(x + 1, (current + 1).toString())
                }
            }
            if (x >= 0 && x <= n - 1) && (y >= 1 && y <= n - 1) {
                if (!arr.get(y - 1).get(x).equals("X")) {
                    let current = arr.get(y - 1).get(x).parseInt(10)
                    arr.get(y - 1).set(x, (current + 1).toString())
                }
            }
            if (x >= 0 && x <= n - 2) && (y >= 0 && y <= n - 2) {
                if (!arr.get(y + 1).get(x + 1).equals("X")) {
                    let current = arr.get(y + 1).get(x + 1).parseInt(10)
                    arr.get(y + 1).set(x + 1, (current + 1).toString())
                }
            }
            if (x >= 1 && x <= n - 1) && (y >= 0 && y <= n - 2) {
                if (!arr.get(y + 1).get(x - 1).equals("X")) {
                    let current = arr.get(y + 1).get(x - 1).parseInt(10)
                    arr.get(y + 1).set(x - 1, (current + 1).toString())
                }
            }
            if (x >= 0 && x <= n - 1) && (y >= 0 && y <= n - 2) {
                if (!arr.get(y + 1).get(x).equals("X")) {
                    let current = arr.get(y + 1).get(x).parseInt(10)
                    arr.get(y + 1).set(x, (current + 1).toString())
                }
            }
        }
        return arr
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a player map with the given size of the board, the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'-' represents the unknown position.
        :return: The player map, ArrayList<ArrayList<String>>.
        >>> MinesweeperGame.generate_playerMap(3)
        [['-', '-', '-'], ['-', '-', '-'], ['-', '-', '-']]

        */
        let arr = ArrayList<ArrayList<String>>()
        for (let i = 0; i < n; i = i + 1) {
            let row = ArrayList<String>()
            for (let j = 0; j < n; j = j + 1) {
                row.add("-")
            }
            arr.add(row)
        }
        return arr
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        /*
        Checks whether the player has won the game,if there are just mines in the player map,return true,otherwise return false.
        :return: true if the player has won the game, false otherwise.
        >>> minesweeper_game = MinesweeperGame(3, 1)
        >>> minesweeper_game.minesweeper_map = ArrayList<ArrayList<String>>([ArrayList<String>(['X', '1', '0']), ArrayList<String>(['1', '1', '0']), ArrayList<String>(['0', '0', '0'])])
        >>> minesweeper_game.player_map = ArrayList<ArrayList<String>>([ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-'])])
        >>> minesweeper_game.check_won(minesweeper_game.player_map)
        false

        */
        for (let i = 0; i < n; i = i + 1) {
            let row = map.get(i)
            for (let j = 0; j < n; j = j + 1) {
                if (row.get(j).equals("-") && !minesweeper_map.get(i).get(j).equals("X")) {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        /*
        Sweeps the given position.
        :param x: The x coordinate of the position, Int64.
        :param y: The y coordinate of the position, Int64.
        :return: true if the player has won the game, false otherwise,if the game still continues, return the player map, ArrayList<ArrayList<String>>.
        >>> minesweeper_game = MinesweeperGame(3, 1)
        >>> minesweeper_game.minesweeper_map = ArrayList<ArrayList<String>>([ArrayList<String>(['X', '1', '0']), ArrayList<String>(['1', '1', '0']), ArrayList<String>(['0', '0', '0'])])
        >>> minesweeper_game.player_map = ArrayList<ArrayList<String>>([ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-']), ArrayList<String>(['-', '-', '-'])])
        >>> minesweeper_game.sweep(1, 1)
        [['-', '-', '-'], ['-', 1, '-'], ['-', '-', '-']]

        */
        if (minesweeper_map.get(x).get(y).equals("X")) {
            return false
        } else {
            player_map.get(x).set(y, minesweeper_map.get(x).get(y))
            score = score + 1
            if (check_won(player_map)) {
                return true
            }
            return player_map
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    /*
    this is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range. 
    */

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        /*
        Initialize movies contains the information about movies
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        /*
        Add a new movie into this.movies
        :param name: String, movie name
        :param price: Float64, price for one ticket
        :param start_time: String
        :param end_time: String
        :param n: Int64, the size of seats(n*n)
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        // Parse the date time strings to DateTime objects
        let startDateTime = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let endDateTime = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        // Create the seats matrix (n x n) filled with zeros
        let seats = ArrayList<ArrayList<Int64>>()
        for i in 0..n {
            let row = ArrayList<Int64>()
            for j in 0..n {
                row.add(0)
            }
            seats.add(row)
        }

        // Create the movie object as a HashMap
        let movie = HashMap<String, Any>()
        movie.add("name", name)
        movie.add("price", price)
        movie.add("start_time", startDateTime)
        movie.add("end_time", endDateTime)
        movie.add("seats", seats)

        // Add the movie to the movies list
        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        /*
        Book tickets for a movie. Change the seats value in this.movies if book successfully.
        :param name: String, movie name
        :param seats_to_book: ArrayList<ArrayList<Int64>>, representing seats to book [[row1, col1], [row2, col2], ...]
        :return: String, booking status message. "Movie not found." for no such movie.
                "Booking success." for successfully booking, or "Booking failed." otherwise
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0]), ArrayList<Int64>([0, 1])]))
        'Booking success.'
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Booking failed.'
        >>> system.book_ticket('batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Movie not found.'
        */
        // Find the movie by name
        for i in 0..movies.size {
            let movie = movies.get(i).unwrap()
            let movieName = movie.get("name").unwrap() as String

            if movieName == name {
                let seats = movie.get("seats").unwrap() as ArrayList<ArrayList<Int64>>

                // Check if all requested seats are available
                for seat in seats_to_book {
                    let row = seat.get(0).unwrap()
                    let col = seat.get(1).unwrap()

                    // If seat is already booked, return booking failed
                    if seats.get(row).unwrap().get(col).unwrap() == 1 {
                        return "Booking failed."
                    }
                }

                // Book all the seats
                for seat in seats_to_book {
                    let row = seat.get(0).unwrap()
                    let col = seat.get(1).unwrap()
                    seats.get(row).unwrap().set(col, 1)
                }

                return "Booking success."
            }
        }

        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        /*
        Get a list of available movies within the specified time range
        :param start_time: String, start time in yyyy/MM/dd HH:mm format
        :param end_time: String, end time in yyyy/MM/dd HH:mm format
        :return: ArrayList<String>, names of available movies
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.available_movies('2023/01/01 12:00', '2023/01/01 22:00')
        ['Batman']
        */
        let startTime = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let endTime = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let available = ArrayList<String>()

        for i in 0..movies.size {
            let movie = movies.get(i).unwrap()
            let movieStartTime = movie.get("start_time").unwrap() as DateTime
            let movieEndTime = movie.get("end_time").unwrap() as DateTime

            // Check if the movie's time range is within the specified range
            if startTime <= movieStartTime && movieEndTime <= endTime {
                let movieName = movie.get("name").unwrap() as String
                available.add(movieName)
            }
        }

        return available
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    /*
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    */

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        /*
        Initializes the music player with an empty playlist, no current song, and a default volume of 50.
        */
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        /*
        Adds a song to the playlist.
        :param song: The song to add to the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.add_song("song1")
        >>> musicPlayer.playlist
        ['song1']

        */
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        /*
        Removes a song from the playlist.
        :param song: The song to remove from the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.remove_song("song1")
        >>> musicPlayer.playlist
        ['song2']

        */
        var index: Int64 = -1
        for (i in 0 ..< this.playlist.size()) {
            if (this.playlist.get(i as Int64) == song) {
                index = i as Int64
                break
            }
        }
        if (index != -1) {
            this.playlist.remove(index)
            if (this.current_song.isSome() && this.current_song.unwrap() == song) {
                this.stop()
            }
        }
    }

    public func play(): Option<String> {
        /*
        Plays the current song in the playlist.
        :return: The current song in the playlist, or "False" if there is no current song, or None if the playlist is empty, Option<String>.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.play()
        'song1'

        */
        if (this.current_song.isSome()) {
            return this.current_song
        } else if (this.playlist.size() > 0) {
            this.current_song = Some(this.playlist.get(0))
            return this.current_song
        } else {
            return None
        }
    }

    public func stop(): Bool {
        /*
        Stops the current song in the playlist.
        :return: true if the current song was stopped, false if there was no current song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.stop()
        true

        */
        if (this.current_song.isSome()) {
            this.current_song = None
            return true
        } else {
            return false
        }
    }

    public func switch_song(): Bool {
        /*
        Switches to the next song in the playlist.
        :return: true if the next song was switched to, false if there was no next song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.switch_song()
        true

        */
        if (this.current_song.isSome()) {
            var currentSong = this.current_song.unwrap()
            var currentIndex: Int64 = -1
            for (i in 0 ..< this.playlist.size()) {
                if (this.playlist.get(i as Int64) == currentSong) {
                    currentIndex = i as Int64
                    break
                }
            }
            if (currentIndex != -1 && currentIndex < this.playlist.size() - 1) {
                this.current_song = Some(this.playlist.get(currentIndex + 1))
                return true
            }
        }
        return false
    }

    public func previous_song(): Bool {
        /*
        Switches to the previous song in the playlist.
        :return: true if the previous song was switched to, false if there was no previous song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song2"
        >>> musicPlayer.previous_song()
        true

        */
        if (this.current_song.isSome()) {
            var currentSong = this.current_song.unwrap()
            var currentIndex: Int64 = -1
            for (i in 0 ..< this.playlist.size()) {
                if (this.playlist.get(i as Int64) == currentSong) {
                    currentIndex = i as Int64
                    break
                }
            }
            if (currentIndex > 0) {
                this.current_song = Some(this.playlist.get(currentIndex - 1))
                return true
            }
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        /*
        Sets the volume of the music player,ifthe volume is between 0 and 100 is valid.
        :param volume: The volume to set the music player to,Int64.
        :return: true if the volume was set, false if the volume was invalid.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.set_volume(50)
        true
        >>> musicPlayer.volume
        50

        */
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist was empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true

        */
        if (this.playlist.size() > 0) {
            var rand = Random()
            var n = this.playlist.size()
            for (i in 0 ..< n) {
                var j = (rand.next() % n) as Int64
                var temp = this.playlist.get(i as Int64)
                this.playlist.set(i as Int64, this.playlist.get(j))
                this.playlist.set(j, temp)
            }
            return true
        } else {
            return false
        }
    }
}

import std.collection.ArrayList

class NLPDataProcessor {

    /*
    The class processes NLP data by removing stop words from a list of strings using a pre-defined stop word list.
    */

    public func construct_stop_word_list(): ArrayList<String> {
        /*
        Construct a stop word list including 'a', 'an', 'the'.
        :return: a list of stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.construct_stop_word_list()
        ['a', 'an', 'the']
        */
        var stop_word_list: ArrayList<String> = ArrayList<String>()
        stop_word_list.add("a")
        stop_word_list.add("an")
        stop_word_list.add("the")
        return stop_word_list
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :param stop_word_list: a list of stop words
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.process(ArrayList<String>(['This is a test.']), ArrayList<String>(['a', 'an', 'the']))
        [['This', 'is', 'test.']]
        */
        var answer: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        for (string in string_list) {
            var string_split: Array<String> = string.split(" ")
            var filtered_words: ArrayList<String> = ArrayList<String>()
            for (word in string_split) {
                if (!stop_word_list.contains(word)) {
                    filtered_words.add(word)
                }
            }
            answer.add(filtered_words)
        }
        return answer
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Construct a stop word list including 'a', 'an', 'the', and remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.']))
        [['This', 'is', 'test.']]
        */
        var stop_word_list: ArrayList<String> = self.construct_stop_word_list()
        var words_list: ArrayList<ArrayList<String>> = self.remove_stop_words(string_list, stop_word_list)
        return words_list
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    /*
    The class processes NLP data by extracting words from a list of strings, calculating the frequency of each word, and returning the top 5 most frequent words.
    */

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        :param string_list: a list of strings
        :return: words_list: a list of words lists
        >>> NLPDataProcessor.process_data(ArrayList<String>(['This is a test.']))
        [['this', 'is', 'a', 'test']]
        */
        var words_list: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        var pattern: Regex = Regex("[^a-zA-Z\\s]")

        for (string in string_list) {
            // Remove non-English letters and convert to lowercase
            var processed_string: String = pattern.replaceAll(string.toLowerCase(), "")
            // Split the string into words
            var words: ArrayList<String> = processed_string.split(" ").filter((s: String) -> Bool { s.length() > 0 })
            words_list.add(words)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        /*
        Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param words_list: a list of words lists
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.calculate_word_frequency(ArrayList<ArrayList<String>>([ArrayList<String>(['this', 'is', 'a', 'test']), ArrayList<String>(['this', 'is', 'another', 'test'])]))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        var word_frequency: HashMap<String, Int64> = HashMap<String, Int64>()

        for (words in words_list) {
            for (word in words) {
                if (word_frequency.contains(word)) {
                    var count: Int64 = word_frequency.get(word).getOrThrow()
                    word_frequency.add(word, count + 1)
                } else {
                    word_frequency.add(word, 1)
                }
            }
        }

        // Convert to array for sorting
        var entries: ArrayList<(String, Int64)> = ArrayList<(String, Int64)>()
        for (key in word_frequency.keys()) {
            var value: Int64 = word_frequency.get(key).getOrThrow()
            entries.add((key, value))
        }

        // Sort by frequency in descending order
        entries.sort((a: (String, Int64), b: (String, Int64)) -> Int64 {
            if (a.1 > b.1) {
                return -1
            } else if (a.1 < b.1) {
                return 1
            } else {
                return 0
            }
        })

        // Take top 5
        var top_5_word_frequency: HashMap<String, Int64> = HashMap<String, Int64>()
        var count: Int64 = 0
        for (entry in entries) {
            if (count >= 5) {
                break
            }
            top_5_word_frequency.add(entry.0, entry.1)
            count = count + 1
        }

        return top_5_word_frequency
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words. Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param string_list: a list of strings
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.', 'This is another test.']))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        var words_list: ArrayList<ArrayList<String>> = self.process_data(string_list)
        var word_frequency_dict: HashMap<String, Int64> = self.calculate_word_frequency(words_list)
        return word_frequency_dict
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    /*
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    */

    public static func decimal_to_binary(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to binary format.
        :param decimal_num: Int64, decimal number
        :return: String, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        */
        return decimal_num.format("b")
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        /*
        Convert a number from binary format to decimal format.
        :param binary_num: String, binary number
        :return: Int64, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        */
        return Int64.parse(binary_num, radix!: 2)
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to octal format.
        :param decimal_num: Int64, decimal number
        :return: String, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        */
        return decimal_num.format("o")
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        /*
        Convert a number from octal format to decimal format.
        :param octal_num: String, octal number
        :return: Int64, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        */
        return Int64.parse(octal_num, radix!: 8)
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to hex format.
        :param decimal_num: Int64, decimal number
        :return hex_num: String, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        */
        return decimal_num.format("x")
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        /*
        Convert a number from hex format to decimal format.
        :param hex_num: String, hex num
        :return: Int64, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        */
        return Int64.parse(hex_num, radix!: 16)
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if (x != null) {
            return this.format_string(x.get())
        } else {
            return ""
        }
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let parts = x.split('.')
        let lstr = parts[0]
        let rstr = if (parts.length > 1) parts[1] else ""

        let lstrrev = this.reverseString(lstr)
        var a = Array<String>(5)
        for (i in 0 .. 5) {
            a[i] = ""
        }

        var lstrrevModified = lstrrev

        if (lstrrevModified.length % 3 == 1) {
            lstrrevModified = lstrrevModified + "00"
        } else if (lstrrevModified.length % 3 == 2) {
            lstrrevModified = lstrrevModified + "0"
        }

        var lm = ""
        var idx = 0
        while (idx < lstrrevModified.length) {
            var end = Math.min(idx + 3, lstrrevModified.length)
            let chunk = lstrrevModified.substring(idx, end)
            let threeDigit = this.reverseString(chunk)
            if (threeDigit != "000") {
                lm = this.trans_three(threeDigit) + " " + this.parse_more((idx / 3) as Int64) + " " + lm
            } else {
                lm = lm + this.trans_three(threeDigit)
            }
            idx += 3
        }

        let xs = if (rstr != "") "AND CENTS " + this.trans_two(rstr) + " " else ""
        if (this.trimString(lm) == "") {
            return "ZERO ONLY"
        } else {
            return this.trimString(lm) + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let padded_s = this.padLeft(s, 2, "0")
        let first_digit = this.charToDigit(padded_s[0])
        let second_digit = this.charToDigit(padded_s[1])

        if (first_digit == 0) {
            return this.NUMBER[second_digit as UInt64]
        } else if (first_digit == 1) {
            return this.NUMBER_TEEN[(first_digit * 10 + second_digit - 10) as UInt64]
        } else if (second_digit == 0) {
            return this.NUMBER_TEN[(first_digit - 1) as UInt64]
        } else {
            return this.NUMBER_TEN[(first_digit - 1) as UInt64] + " " + this.NUMBER[second_digit as UInt64]
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let first_digit = this.charToDigit(s[0])
        let remaining = s.substring(1)

        if (first_digit == 0) {
            return this.trans_two(remaining)
        } else if (remaining == "00") {
            return this.NUMBER[first_digit as UInt64] + " HUNDRED"
        } else {
            return this.NUMBER[first_digit as UInt64] + " HUNDRED AND " + this.trans_two(remaining)
        }
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i >= 0 && i < this.NUMBER_MORE.length as Int64) {
            return this.NUMBER_MORE[i as UInt64]
        } else {
            return ""
        }
    }

    private func reverseString(s: String): String {
        var result = ""
        var i = s.length - 1
        while (i >= 0) {
            result = result + s[i]
            i -= 1
        }
        return result
    }

    private func trimString(s: String): String {
        var start = 0
        var end = s.length
        while (start < end && (s[start] == ' ' || s[start] == '\t' || s[start] == '\n')) {
            start += 1
        }
        while (end > start && (s[end - 1] == ' ' || s[end - 1] == '\t' || s[end - 1] == '\n')) {
            end -= 1
        }
        return s.substring(start, end)
    }

    private func padLeft(s: String, length: Int64, padChar: String): String {
        var result = s
        while (result.length < length) {
            result = padChar + result
        }
        return result
    }

    private func charToDigit(c: Char): Int64 {
        return c as Int64 - '0' as Int64
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        let out = ArrayList<Rune>()
        var pos = 0
        let length = string.len()

        let runes = string.runes()
        let runeArray = ArrayList<Rune>()
        for (r in runes) {
            runeArray.add(r)
        }

        while pos < length - 2 {
            if runeArray.get(pos) == Rune.fromInt32('&'.int32()) && runeArray.get(pos + 1) == Rune.fromInt32('#'.int32()) {
                let start = pos + 2
                var is_hex = false
                let first_char = runeArray.get(start)

                if first_char == Rune.fromInt32('x'.int32()) || first_char == Rune.fromInt32('X'.int32()) {
                    is_hex = true
                }

                var actual_start = start
                if is_hex {
                    actual_start = start + 1
                }

                if actual_start == length {
                    var result = ""
                    for (r in out) {
                        result += r.toUtf8String()
                    }
                    return result
                }

                var end = actual_start
                while end < length && NumericEntityUnescaper.is_hex_char(runeArray.get(end)) {
                    end += 1
                }

                if end < length && runeArray.get(end) == Rune.fromInt32(';'.int32()) {
                    var entity_str = ""
                    for i in actual_start..end {
                        entity_str += runeArray.get(i).toUtf8String()
                    }

                    try {
                        let radix = if is_hex { 16 } else { 10 }
                        let entity_value = Int64.fromRadixString(entity_str, radix)
                        out.add(Rune.fromInt32(entity_value.int32()))
                        pos = end + 1
                        continue
                    } catch (e: Exception) {
                        var result = ""
                        for (r in out) {
                            result += r.toUtf8String()
                        }
                        return result
                    }
                }
            }

            out.add(runeArray.get(pos))
            pos += 1
        }

        // Add any remaining characters
        while pos < length {
            out.add(runeArray.get(pos))
            pos += 1
        }

        var result = ""
        for (r in out) {
            result += r.toUtf8String()
        }
        return result
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true

        */
        let char_val = char.toUtf8String()
        if char_val.len() == 1 {
            let c = char_val.get(0)
            return (c >= '0'.int8() && c <= '9'.int8()) || 
                   (c >= 'a'.int8() && c <= 'f'.int8()) || 
                   (c >= 'A'.int8() && c <= 'F'.int8())
        }
        return false
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Dish <: Equatable<Dish> {

    let dish: String
    let price: Int64
    var count: Int64

    public init(dish: String, price: Int64, count: Int64) {
        this.dish = dish
        this.price = price
        this.count = count
    }

    public override operator func != (that: Dish): Bool {
        return this.dish != that.dish || this.price != that.price || this.count != that.count
    }

    public override operator func == (that: Dish): Bool {
        return this.dish == that.dish && this.price == that.price && this.count == that.count
    }
}

class Order {

    /*
    The class manages restaurant orders by allowing the addition of dishes, calculation of the total cost, and checkout.
    */

    let menu: ArrayList<Dish>
    let selected_dishes: ArrayList<Dish>
    let sales: HashMap<String, Float64>

    public init() {
        /*
        Initialize the order management system
        this.menu stores the dishes of resturant inventory
        menu = [Dish("dish name", price, count), ...]
        this.selected_dishes stores the dished selected by customer
        selected_dish = Dish("dish name", price, count)
        this.sales stores the sales of each dish
        sales = {dish name: sales}
        */
        this.menu = ArrayList<Dish>()
        this.selected_dishes = ArrayList<Dish>()
        this.sales = HashMap<String, Float64>()
    }

    public func add_dish(dish: Dish): Bool {
        /*
        Check the this.menu and add into this.selected_dish if the dish count is valid.
        And if the dish has successfully been added, change the count in this.menu.
        :param dish: Dish, the information of dish.
        :return: true if successfully added, or false otherwise.
        >>> order = Order()
        >>> order.menu.add(Dish("dish1", 10, 5))
        >>> order.add_dish(Dish("dish1", 10, 3))
        true
        */
        for (menu_dish in this.menu) {
            if (dish.dish == menu_dish.dish) {
                if (menu_dish.count < dish.count) {
                    return false
                } else {
                    menu_dish.count -= dish.count
                    break
                }
            }
        }
        this.selected_dishes.add(dish)
        return true
    }

    public func calculate_total(): Float64 {
        /*
        Calculate the total price of dishes that have been ordered. Multiply the count, price and sales.
        :return total: Float64, the final total price.
        >>> order = Order()
        >>> order.menu.add(Dish("dish1", 10, 5))
        >>> order.sales = {"dish1": 0.8}
        >>> order.add_dish(Dish("dish1", 10, 4))
        true
        >>> order.calculate_total()
        32.0
        */
        var total: Float64 = 0.0
        for (dish in this.selected_dishes) {
            var sale: Float64 = this.sales.get(dish.dish).getOrThrow()
            total += Float64.from(dish.price) * Float64.from(dish.count) * sale
        }
        return total
    }

    public func checkout(): Option<Float64> {
        /*
        Check out the dished ordered. IF the this.selected_dishes is not empty, invoke the calculate_total
        method to check out.
        :return None if the this.selected_dishes is empty, or total(return value of calculate_total) otherwise.
        >>> order = Order()
        >>> order.menu.add(Dish("dish1", 10, 5))
        >>> order.sales = {"dish1": 0.8}
        >>> order.add_dish(Dish("dish1", 10, 4))
        true
        >>> order.checkout()
        32.0
        */
        if (this.selected_dishes.size() == 0) {
            return Option<Float64>.None
        }
        var total: Float64 = this.calculate_total()
        this.selected_dishes.clear()
        return Option<Float64>.Some(total)
    }
}

import std.collection.ArrayList

class PageInfo <: Equatable<PageInfo> {

    let current_page: Int64
    let per_page: Int64
    let total_pages: Int64
    let total_items: Int64
    let has_previous: Bool
    let has_next: Bool
    let data: ArrayList<Int64>

    public init(current_page: Int64, per_page: Int64, total_pages: Int64, total_items: Int64, has_previous: Bool, has_next: Bool, data: ArrayList<Int64>) {
        this.current_page = current_page
        this.per_page = per_page
        this.total_pages = total_pages
        this.total_items = total_items
        this.has_previous = has_previous
        this.has_next = has_next
        this.data = data
    }

    public override operator func != (that: PageInfo): Bool {
        return this.current_page != that.current_page || this.per_page != that.per_page || this.total_pages != that.total_pages || this.total_items != that.total_items || this.has_previous != that.has_previous || this.has_next != that.has_next || this.data != that.data
    }

    public override operator func == (that: PageInfo): Bool {
        return this.current_page == that.current_page && this.per_page == that.per_page && this.total_pages == that.total_pages && this.total_items == that.total_items && this.has_previous == that.has_previous && this.has_next == that.has_next && this.data == that.data
    }
}

